--- a/secp256r1/src/group.rs
+++ b/secp256r1/src/group.rs
@@ -635,11 +635,24 @@
-        for i in (0..261).rev() {
-            out = out.double();
-            for (table, naf) in affine.chunks_exact(8).zip(&nafs) {
-                let digit = naf[i];
-                if digit > 0 {
-                    out = out.add_mixed(table[(digit >> 1) as usize]);
-                } else if digit < 0 {
-                    out = out.add_mixed(-table[((-digit) >> 1) as usize]);
-                }
-            }
-        }
+        for i in (0..261).rev() {
+            // The doubling is folded into the first nonzero digit's addition.
+            let mut doubled = false;
+            for (table, naf) in affine.chunks_exact(8).zip(&nafs) {
+                let digit = naf[i];
+                if digit == 0 {
+                    continue;
+                }
+                let entry = if digit > 0 {
+                    table[(digit >> 1) as usize]
+                } else {
+                    -table[((-digit) >> 1) as usize]
+                };
+                out = if doubled {
+                    out.add_mixed(entry)
+                } else {
+                    out.double_add_mixed(entry)
+                };
+                doubled = true;
+            }
+            if !doubled {
+                out = out.double();
+            }
+        }

